# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)
# Put a person on hold, or take them off it when held; a person not on the sheet is refused (404).
# While held, their open claims count in no live total; their settled claims still do.
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonHeld
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# The sheet's people, in the order they were added.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: people
people:
  class: net.officefloor.hq.app.person.LoadPeople
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off it when they are held. */
public class HoldPerson {
    public void hold(@Val Person person, PersonRepository people, Out<Person> updated) {
        updated.set(people.hold(person, !person.held()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the person just put on hold, or just taken off it. */
public class AuditPersonHeld {
    public void audit(@Val Person person, @RequestParam("user") String user, Audit audit) {
        audit.record((person.held() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.sheetId() + " by="
                + user + " name=" + person.name());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;

/**
 * A person on a sheet. {@code id} is null until the person is first saved; {@code version} counts its saves.
 * {@code statementCount} counts the statements taken; {@code statedTotal} is the last one's due-total
 * (n/a when it had none) and {@code statementDate} the sheet's today when it was taken, both null before the first.
 * {@code retiredFrom} is the date the person is retired from, or null when they are not retired. {@code held} is
 * whether the person is on hold: their open claims then count in no live total.
 */
public record Person(Long id, String sheetId, String name, String grade, int version, int statementCount,
        String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held) {

    /** The same person with another name and grade. */
    public Person withNameAndGrade(String nextName, String nextGrade) {
        return new Person(id, sheetId, nextName, nextGrade, version, statementCount, statedTotal, statementDate,
                retiredFrom, held);
    }

    /** Whether the claim counts toward this person's live totals: a held person's open claims do not. */
    public boolean counts(Claim claim) {
        return claim.counts(held);
    }

    /** Whether the person is retired: a retirement date is set, whatever the date. */
    public boolean retired() {
        return retiredFrom != null;
    }

    /** Whether a claim on this date is refused: the person is retired from an earlier date. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

/**
 * A person as the screen shows them; the last statement's due-total and date are null before the first, and
 * {@code retiredFrom} is null while they are not retired; {@code held} is whether they are on hold.
 */
public record PersonResponse(long id, String name, String grade, int version, int statementCount, String statedTotal,
        String statementDate, boolean retired, String retiredFrom, boolean held) {

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.id(), person.name(), person.grade(), person.version(), person.statementCount(),
                person.statedTotal(), person.statementDate() == null ? null : person.statementDate().toString(),
                person.retired(), person.retiredFrom() == null ? null : person.retiredFrom().toString(),
                person.held());
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class LoadPeople {
    public void load(@Val Sheet sheet, PersonRepository repository, Out<List<Person>> people) {
        people.set(repository.findAll(sheet.id()));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val List<Person> people, ObjectResponse<List<PersonResponse>> response) {
        response.send(people.stream().map(PersonResponse::from).toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            PersonRepository repository, Out<Person> person) throws PersonNotFoundException {
        Person found = repository.find(sheetId, personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, grade, version, statement_count, stated_total, statement_date, retired_from, held";

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in the order they were added. */
    public List<Person> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
                PersonRepository::map, sheetId);
    }

    /** The person with this id on this sheet, or null. */
    public Person find(String sheetId, long id) {
        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                PersonRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on this sheet with this name, ignoring case, or null. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                PersonRepository::map, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether a person other than {@code exceptId} on the sheet has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheetId, name, exceptId, exceptId);
        return n != null && n > 0;
    }

    /**
     * Insert a new person (null id) or update an existing one, bumping its version; the person as
     * stored, or null when the stored version is no longer the one the person was loaded at.
     */
    public Person save(Person person) {
        if (person.id() != null) {
            int n = jdbc.update(
                    "UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
                    person.name(), person.grade(), person.id(), person.sheetId(), person.version());
            return n == 0 ? null
                    : new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version() + 1,
                            person.statementCount(), person.statedTotal(), person.statementDate(),
                            person.retiredFrom(), person.held());
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
            ps.setString(1, person.sheetId());
            ps.setString(2, person.name());
            ps.setString(3, person.grade());
            return ps;
        }, keys);
        return new Person(keys.getKey().longValue(), person.sheetId(), person.name(), person.grade(), 0, 0, null, null,
                null, false);
    }

    /**
     * Record a statement just taken of the person: one more statement, with its due-total and date; the
     * person as stored. Not an edit, so it leaves the version alone.
     */
    public Person recordStatement(Person person, String statedTotal, LocalDate date) {
        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ?"
                + " WHERE id = ? AND sheet_id = ?", statedTotal, Date.valueOf(date), person.id(), person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Retire the person from this date; the person as stored. Not an edit, so it leaves the version alone. */
    public Person retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(from), person.id(),
                person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Put the person on hold or take them off it; the person as stored. Not an edit, so it leaves the version alone. */
    public Person hold(Person person, boolean held) {
        jdbc.update("UPDATE person SET held = ? WHERE id = ? AND sheet_id = ?", held, person.id(), person.sheetId());
        return find(person.sheetId(), person.id());
    }

    private static Person map(ResultSet rs, int n) throws SQLException {
        return new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"),
                rs.getInt("version"), rs.getInt("statement_count"), rs.getString("stated_total"),
                rs.getObject("statement_date", LocalDate.class),
                rs.getObject("retired_from", LocalDate.class), rs.getBoolean("held"));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPerson {
    public void handle(@Parameter InvalidPersonException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.person;

public class InvalidPersonException extends Exception {
    public InvalidPersonException(String message) {
        super(message);
    }
}
-- A person can be put on hold: while held, their open claims count in no live total (settled ones still do).
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- People kept on a sheet, listed in the order they were added (id order). grade is one of A, B, C.
CREATE TABLE person (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    grade VARCHAR(1) NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person can be retired from a date: they count as retired at once, whatever the date, and a claim
-- dated after it is refused. Null while the person is not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;

