import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonHold } from './PersonHold';

export const contributions = [
  PersonColumnHeads.fill({ order: 19, Component: () => <th>Hold</th> }),
  PersonColumns.fill({ order: 19, Component: PersonHold }),
];
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { usePersonError } from '../people/personError';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// Whether the person is on hold, and the button that puts them on hold or takes them off it. While
// held, their open claims count in no live total; their settled claims still do.
export function PersonHold({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = usePersonError(person.id);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const hold = useMutation({
    mutationFn: () =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: () => setError(person.held ? 'The person could not be released.' : 'The person could not be held.'),
  });

  const submit = () => {
    setError('');
    once(() => hold.mutateAsync());
  };

  return (
    <td>
      <span data-testid="person-hold">{person.held ? 'yes' : 'no'}</span>{' '}
      <button type="button" data-testid="person-hold-toggle" disabled={hold.isPending} onClick={submit}>
        {person.held ? 'Release' : 'Hold'}
      </button>
    </td>
  );
}
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { personDue, useRates } from './rates';

// A person's due-total: the figures of their claims that count, added up; n/a when their grade has no
// rate on the sheet's today, unless a settled or stated claim keeps a figure.
export function PersonDueTotal({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-due-total">{personDue(claims, rates, person.grade, person.held, rules)}</td>;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/**
 * A person on the sheet as the store holds them; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they are on hold: their open claims then count in no live total.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
};

/** The fields the person form submits. */
export type PersonInput = { name: string; grade: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);

/** Whether retired people are listed; off until the toggle is turned on, and kept when a sheet is loaded. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useSyncExternalStore } from 'react';
import { useCurrentSheet } from '../session/session';

// One error per person row, shared by every action on the row (a statement, a retirement, ...): the
// row shows it once, in its last cell, and the next action on the row clears it.
const errors = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The person row's error ('' when none) and the setter every action on the row uses. */
export function usePersonError(personId: number): [string, (message: string) => void] {
  const [sheet] = useCurrentSheet();
  const key = `${sheet}:${personId}`;
  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
  const setError = (message: string) => {
    if (message) errors.set(key, message);
    else errors.delete(key);
    listeners.forEach((l) => l());
  };
  return [error, setError];
}

/** The person row's error, when there is one. */
export function PersonError({ personId }: { personId: number }) {
  const [error] = usePersonError(personId);
  return error ? <span data-testid="person-error">{error}</span> : null;
}
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Extra column headers of the people table: each contribution renders its own <th>. */
export const PersonColumnHeads = defineSlot('people.columnHeads');

/** Extra cells of a person's row, in the same order as PersonColumnHeads: each renders its own <td>. */
export const PersonColumns = defineSlot<{ person: Person }>('people.columns');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

