# Retire a person from a date (blank: the sheet's today); a bad date is refused (400), a person not on the
# sheet (404). Their claims keep counting in every total; a claim dated after the date is refused from now on.
validate:
  class: net.officefloor.hq.app.person.ValidateRetireRequest
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses (400) a retirement date that is not yyyy-mm-dd; a blank one is the sheet's today. */
public class ValidateRetireRequest {
    public void validate(@RequestBody @Valid RetireRequest request, Out<Retirement> retirement)
            throws InvalidPersonException {
        String from = request.from() == null ? "" : request.from().trim();
        if (from.isEmpty()) {
            retirement.set(new Retirement(null));
            return;
        }
        try {
            retirement.set(new Retirement(LocalDate.parse(from)));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The retirement date must be yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.constraints.Size;

/** The date a person is retired from, as the row submits it (yyyy-mm-dd); blank is the sheet's today. */
public record RetireRequest(@Size(max = 30) String from) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date given, or the sheet's today when it was left blank. */
public class RetirePerson {
    public void retire(@Val Person person, @Val Retirement retirement, PersonRepository people,
            SheetRepository sheets, Out<Person> updated) {
        updated.set(people.retire(person,
                retirement.from() != null ? retirement.from() : sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the person just retired and the date they are retired from. */
public class AuditPersonRetired {
    public void audit(@Val Person person, @RequestParam("user") String user, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.sheetId() + " by=" + user + " name=" + person.name()
                + " from=" + person.retiredFrom());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is overdue.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(15, 2) NOT NULL DEFAULT 0.00;
